contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        address ownerBefore = c.owner();

        bool reverted;
        if (caller == ownerBefore) {
            // Owner path: setOwner must succeed and change owner to newOwner.
            try c.setOwner(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted && c.owner() == newOwner);
        } else {
            // Non-owner path: setOwner must revert and leave owner unchanged.
            try c.setOwner(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted && c.owner() == ownerBefore);
        }
    }
}

