        // Ensure this test contract is the current owner, as it deployed c.
        require(c.owner() == address(this));

        address ownerBefore = c.owner();

        bool reverted;
        bool returned;

        // The deciding call: owner calls setOwner with a new owner (may be same).
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            returned = success;
        } catch {
            reverted = true;
            returned = false;
        }

        // General rule: an owner call must succeed, return true, and set owner to newOwner.
